const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths=['M7 3v5h10V3M12 8v7m-5 0h10v6H7z','m13 2-8 12h6l-1 8 9-13h-7z','M3 8h18V3H3zm3 4v4m6-4v8m6-8v4','m14 5 5 5M3 21l9-9m-4-9 4 4 4-1 2-4 4 4-1 5-5 2-3 3-5-5-3-5z','m12 3-3 9m-3 0h9l4 9H2zm-1 5h12','M12 5v14M5 12h14'];
const cats=['ВиК','Електро','Климатизация','Ремонти','Почистване','Други'];
const catalog=[['Смяна на смесител','Отстраняване на теч — оглед'],['Смяна на контакт','Електрически проблем — диагностика'],['Почистване на климатик','Ремонт на климатик — диагностика'],['Боядисване — оглед','Ремонт на баня — оглед'],['Почистване на дом до 80 м²','Почистване на общи части — оглед'],['Друга услуга — оглед']];
const rates=[45,35,55,25,65,25];let homeRate=1.5,entryRate=18,view='home',role='client',plan=null;
const requests=[{id:1001,cat:0,service:'Смяна на смесител',address:'София · ул. Примерна 12',date:'Демо посещение',time:'09:00–12:00',price:45,status:1,desc:'Подмяна на смесителя в кухнята.',master:'Демо специалист · ВиК'},{id:1002,cat:4,service:'Почистване на дом',address:'София · ул. Примерна 12',date:'Демо посещение',time:'12:00–15:00',price:65,status:4,desc:'Почистване на апартамент до 80 м².',master:'Демо екип · Почистване',report:'Почистени подове, кухня и санитарни помещения.'}];const stages=['Създадена','Приета','Специалистът пътува','В процес','Очаква потвърждение','Завършена'];
function icon(i){return `<svg viewBox="0 0 24 24" fill="none" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[i]}"></path></svg>`}function money(n){return new Intl.NumberFormat('bg-BG',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n)}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4200)}
function rows(items,actions=false){return items.length?items.map(r=>`<article class="request"><div class="tinyicon">${icon(r.cat)}</div><div class="requestinfo"><h3>${esc(r.service)}</h3><p>${esc(r.date)} · ${esc(r.time)}<br>${esc(r.address)}</p><span class="badge ${r.status===0?'wait':''}">${r.cancelled?'Отказана':stages[r.status]}</span>${r.plan?` <span class="badge">${r.plan==='home'?'За дома':'За входа'}</span>`:''}${actions?`<p>${esc(r.master||'Очаква разпределяне към специалист')}</p>${r.report?`<p>Отчет: ${esc(r.report)}</p>`:''}<div class="actions">${!r.cancelled&&r.status<4&&role==='client'?`<button class="secondary" data-cancel="${r.id}">Откажи заявката</button>`:''}${!r.cancelled&&role!=='client'&&r.status<4?`<button class="primary" data-next="${r.id}">${r.status===0?'Приеми заявката':r.status===3?'Добави отчет':'Следващ статус'}</button>${r.status===0?`<button class="secondary" data-decline="${r.id}">Откажи изпълнение</button>`:''}`:''}${!r.cancelled&&r.status===4&&role==='client'?`<button class="primary" data-complete="${r.id}">Потвърди приключването</button><button class="secondary" data-issue="${r.id}">Има проблем</button>`:''}${r.status===5&&!r.rating&&role==='client'?`<span>Оценете:</span>${[1,2,3,4,5].map(n=>`<button class="starbutton" aria-label="${n} звезди" data-rate="${r.id}:${n}">${n}★</button>`).join('')}`:''}${r.rating?`<span class="muted">Оценка: ${r.rating}/5 ★</span>`:''}</div>${r.issue?'<p class="notice">Подаден демо сигнал. Очаква преглед от DOMORA.</p>':''}`:''}</div><span class="amount">${money(r.price)}${r.plan?'<small> / мес.</small>':''}</span></article>`).join(''):'<div class="empty">Все още няма заявки. Изберете услуга, за да започнете.</div>'}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('selected',b.dataset.view===view));let html='';if(role!=='client'){html=`<div class="heading"><div><span class="eyebrow">ДЕМО РАБОТНО ПРОСТРАНСТВО</span><h1>${role==='master'?'Задачите ви, подредени.':'Общ поглед върху DOMORA'}</h1><p class="muted">${role==='master'?'Приемайте задачи и отчитайте извършената работа.':'Управлявайте заявките и демонстрационните тарифи.'}</p></div></div><div class="stats"><div class="card">Общо заявки<strong>${requests.length}</strong></div><div class="card">Активни<strong>${requests.filter(r=>!r.cancelled&&r.status<5).length}</strong></div><div class="card">Приключени<strong>${requests.filter(r=>r.status===5).length}</strong></div></div><div class="card">${rows(requests,true)}</div>${role==='admin'?`<div class="sectionhead"><h2>Демонстрационни тарифи</h2></div><div class="card"><p class="muted">Цените се прилагат за нови заявки. Съществуващите запазват одобрената цена.</p><form id="tariffs"><div class="priceinputs">${cats.map((c,i)=>`<label>${c} · базова цена (€)<input type="number" min="1" max="10000" required name="rate${i}" value="${rates[i]}"></label>`).join('')}<label>За дома · €/м² месечно<input name="home" type="number" min="0.1" max="100" step="0.1" required value="${homeRate}"></label><label>За входа · €/етаж месечно<input name="entry" type="number" min="1" max="1000" required value="${entryRate}"></label></div><button class="primary">Запази демо тарифите</button></form></div>`:''}`;}else if(view==='home'){html=`<div class="heading"><div><span class="eyebrow">ДОБРЕ ДОШЛИ В DOMORA</span><h1>Спокойствие за вашия дом.</h1><p class="muted">Всичко за дома, подредено на едно място.</p></div><button class="primary" data-book="0">+ Нова заявка</button></div><div class="banner"><div><span class="eyebrow">ПО-МАЛКО ЗАДАЧИ. ПОВЕЧЕ ВРЕМЕ.</span><h2>Грижата за дома<br>може да бъде по-лесна.</h2><p>Изберете абонамент за дома или входа и планирайте редовното почистване.</p></div><button class="secondary" data-go="plans">Разгледай абонаментите ↗</button></div><div class="sectionhead"><h2>От какво се нуждаете?</h2><span class="muted">6 категории</span></div><div class="services">${cats.map((c,i)=>`<button class="service" data-book="${i}">${icon(i)}${c}</button>`).join('')}</div><div class="lower"><section><div class="sectionhead"><h2>Последни заявки</h2><button class="textbutton" data-go="requests">Всички →</button></div><div class="card">${rows(requests.slice(0,2))}</div></section><section><div class="sectionhead"><h2>Вашият абонамент</h2></div><div class="card"><span class="badge">Грижа по график</span><h3 style="margin-top:16px">Повече време за вас.</h3><p class="muted" style="margin-top:10px">Две почиствания месечно за дома или седмична грижа за общите части.</p><button class="secondary full" data-go="plans">Избери план</button><div class="planhint">Обхватът и цената са ясни преди потвърждение.</div></div></section></div>`;}else if(view==='plans'){html=`<div class="heading"><div><span class="eyebrow">ГРИЖА, КОЯТО ПРОДЪЛЖАВА</span><h1>Един дом. Или цял вход.</h1><p class="muted">Два отделни плана, съобразени с вашето пространство.</p></div></div><div class="plans"><div class="card plancard featured"><span class="badge">За домакинства</span><h2>DOMORA За дома</h2><p class="muted">Редовно почистване на апартамент или къща.</p><div class="planprice">${money(homeRate*80)} <small class="muted">/ месец*</small></div><p class="muted">Демо пример за 80 м²</p><ul><li>2 почиствания месечно</li><li>Подове и достъпни повърхности</li><li>Кухня и санитарни помещения</li><li>Отчет след всяко посещение</li><li>История на услугите</li></ul><button class="primary" data-plan="home">Избери „За дома“ →</button></div><div class="card plancard"><span class="badge">За етажна собственост</span><h2>DOMORA За входа</h2><p class="muted">Поддържани общи части по постоянен график.</p><div class="planprice">${money(entryRate*6)} <small class="muted">/ месец*</small></div><p class="muted">Демо пример за 6 етажа · цена за целия вход</p><ul><li>Почистване веднъж седмично</li><li>Стълби и етажни площадки</li><li>Входна врата и парапети</li><li>Отчет след всяко посещение</li><li>Контакт чрез представител на входа</li></ul><button class="primary" data-plan="entry">Избери „За входа“ →</button></div></div><p class="notice">* Всички цени са демонстрационни. Ремонти, материали и извънредно почистване се оферират отделно. Изборът създава демо заявка за абонамент, без плащане.</p>`;}else{html=`<div class="heading"><div><span class="eyebrow">ВСИЧКО НА ЕДНО МЯСТО</span><h1>Моите заявки</h1><p class="muted">Следете текущите услуги и разглеждайте историята си.</p></div><button class="primary" data-book="0">+ Нова заявка</button></div><div class="card">${rows(requests,true)}</div>`;}$('#main').innerHTML=html;const tf=$('#tariffs');if(tf)tf.onsubmit=e=>{e.preventDefault();rates.forEach((_,i)=>rates[i]=Number(tf.elements['rate'+i].value));homeRate=Number(tf.elements.home.value);entryRate=Number(tf.elements.entry.value);toast('Демо тарифите са обновени.');};}
function quote(){const c=+$('#category').value,s=+$('#service').value;return plan?Math.round((+$('#quantity').value||1)*(plan==='home'?homeRate:entryRate)):s>0?25:rates[c]}
function updateQuote(){$('#price').textContent=money(quote())+(plan?' / месец':'');$('#scope').textContent=plan?(plan==='home'?'2 почиствания месечно':'Почистване веднъж седмично'):(+$('#service').value>0||[3,5].includes(+$('#category').value)?'Цена само за оглед / диагностика. Ремонтът е с отделна оферта.':'Труд за избраната услуга. Материалите се заплащат отделно.');}
function services(){const c=+$('#category').value;$('#service').innerHTML=catalog[c].map((s,i)=>`<option value="${i}">${s}</option>`).join('');updateQuote()}
function openBooking(c=0,p=null){plan=p;$('#form').reset();$('#previews').innerHTML='';$('#category').innerHTML=cats.map((s,i)=>`<option value="${i}">${s}</option>`).join('');$('#category').value=String(c);$('#category').disabled=!!p;$('#service').disabled=!!p;$('#planfields').hidden=!p;$('#quantity').value=p==='entry'?6:80;$('#quantity').previousSibling.textContent=p==='entry'?'Брой етажи':'Площ на дома (м²)';$('#dialogtitle').textContent=p?`Абонамент ${p==='home'?'за дома':'за входа'}`:'Разкажете ни от какво се нуждаете';const now=new Date();const today=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;$('#date').min=today;services();if(p){$('#service').innerHTML='<option value="0">'+(p==='home'?'Абонаментно почистване на дома':'Абонаментно почистване на общите части')+'</option>';}$('#booking').showModal();}
$('#category').onchange=services;$('#service').onchange=updateQuote;$('#quantity').oninput=updateQuote;$('#close').onclick=()=>$('#booking').close();let imageUrls=[];$('#photos').onchange=()=>{imageUrls.forEach(URL.revokeObjectURL);imageUrls=[];$('#previews').innerHTML='';Array.from($('#photos').files).slice(0,5).forEach(f=>{if(!f.type.startsWith('image/')||f.size>10*1024*1024){toast('Използвайте изображения до 10 MB.');return;}const u=URL.createObjectURL(f);imageUrls.push(u);const im=document.createElement('img');im.src=u;im.alt='Преглед на избрана снимка';$('#previews').append(im)})};
$('#form').onsubmit=e=>{e.preventDefault();if(!$('#form').reportValidity())return;requests.unshift({id:Date.now(),cat:+$('#category').value,service:plan?`Абонамент ${plan==='home'?'За дома':'За входа'}`:catalog[+$('#category').value][+$('#service').value],address:$('#address').value,date:$('#date').value,time:$('#time').value,price:quote(),status:0,desc:$('#description').value,plan});$('#booking').close();view='requests';role='client';$('#role').value=role;render();toast('Демо заявката е създадена. Не е изпратена до реален специалист.');};
$('#role').onchange=()=>{role=$('#role').value;render()};document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.view||d.go){view=d.view||d.go;role='client';$('#role').value=role;render()}if(d.book!==undefined)openBooking(+d.book);if(d.plan)openBooking(4,d.plan);if(d.cancel){const r=requests.find(r=>r.id===+d.cancel);if(confirm('Да отменим ли тази демо заявка?')){r.cancelled=true;render();toast('Заявката е отказана.')}}if(d.next){const r=requests.find(r=>r.id===+d.next);if(r.status===3){const report=prompt('Опишете извършената работа (демо отчет):');if(!report?.trim())return;r.report=report.trim();}r.status++;r.master=r.master||'Демо специалист · DOMORA';render();toast('Статусът е обновен.')}if(d.decline){const r=requests.find(r=>r.id===+d.decline);r.master='Очаква нов изпълнител';render();toast('Заявката остава за преразпределяне.')}if(d.complete){requests.find(r=>r.id===+d.complete).status=5;render();toast('Услугата е приключена. Можете да оставите оценка.')}if(d.issue){requests.find(r=>r.id===+d.issue).issue=true;render();toast('Демо сигналът е отбелязан за преглед.')}if(d.rate){const [id,n]=d.rate.split(':').map(Number);requests.find(r=>r.id===id).rating=n;render();toast('Благодарим за оценката!')}});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_domora_request',description:'Отваря формата за нова демо заявка; не изпраща заявка.',inputSchema:{type:'object',properties:{category:{type:'integer',minimum:0,maximum:5}},required:['category'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!Number.isInteger(input.category)||input.category<0||input.category>5)throw new Error('Невалидна категория');openBooking(input.category);return {opened:true,category:cats[input.category]}}})).catch(()=>{});}catch{}}
render();
